CREATE OR REPLACE FUNCTION public.begin_email_otp_challenge()
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_id uuid;
begin
 if (select auth.uid()) is null or nullif((select auth.jwt()->>'session_id'),'') is null then
  raise exception 'Sign in with your password first.' using errcode='42501';
 end if;
 if not exists(select 1 from jsonb_array_elements(coalesce((select auth.jwt()->'amr'),'[]'::jsonb)) a where a->>'method'='password') then
  raise exception 'A password sign-in is required before email verification.' using errcode='42501';
 end if;
 if not exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.password_configured_at is not null) then
  raise exception 'Set your SubnetLab password first.' using errcode='42501';
 end if;
 delete from public.email_otp_challenges where user_id=(select auth.uid()) and (expires_at<now() or consumed_at is not null);
 insert into public.email_otp_challenges(user_id,password_session_id)
 values((select auth.uid()),nullif((select auth.jwt()->>'session_id'),'')::uuid) returning id into v_id;
 return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_email_otp_challenge(p_challenge_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_challenge public.email_otp_challenges%rowtype; v_session uuid:=nullif((select auth.jwt()->>'session_id'),'')::uuid;
begin
 if (select auth.uid()) is null or v_session is null then raise exception 'Sign in again to verify your email.' using errcode='42501'; end if;
 if not exists(select 1 from jsonb_array_elements(coalesce((select auth.jwt()->'amr'),'[]'::jsonb)) a where a->>'method' in ('otp','magiclink','email/signup')) then
  raise exception 'The session was not created by an email OTP.' using errcode='42501';
 end if;
 select * into v_challenge from public.email_otp_challenges
  where id=p_challenge_id and user_id=(select auth.uid()) and consumed_at is null and expires_at>now()
  for update;
 if not found then raise exception 'This email verification request expired. Send a new code.' using errcode='22023'; end if;
 if v_challenge.password_session_id=v_session then raise exception 'A fresh email verification session is required.' using errcode='42501'; end if;
 insert into public.email_otp_verified_sessions(user_id,session_id,expires_at)
 values((select auth.uid()),v_session,now()+interval '12 hours')
 on conflict(user_id,session_id) do nothing;
 update public.email_otp_challenges set consumed_at=now() where id=p_challenge_id;
 return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.consume_api_rate_limit(p_key_hash text, p_limit integer, p_window_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_count integer;
  v_expires timestamptz;
begin
  if p_key_hash is null or length(p_key_hash) <> 64
     or p_limit < 1 or p_limit > 100000
     or p_window_seconds < 1 or p_window_seconds > 86400 then
    raise exception using errcode = '22023', message = 'Invalid rate limit parameters';
  end if;

  insert into public.api_rate_limits(key_hash, window_started_at, request_count, expires_at)
  values (p_key_hash, v_now, 1, v_now + pg_catalog.make_interval(secs => p_window_seconds))
  on conflict (key_hash) do update
  set window_started_at = case
        when public.api_rate_limits.expires_at <= v_now then v_now
        else public.api_rate_limits.window_started_at end,
      request_count = case
        when public.api_rate_limits.expires_at <= v_now then 1
        else public.api_rate_limits.request_count + 1 end,
      expires_at = case
        when public.api_rate_limits.expires_at <= v_now then v_now + pg_catalog.make_interval(secs => p_window_seconds)
        else public.api_rate_limits.expires_at end
  returning request_count, expires_at into v_count, v_expires;

  -- Opportunistic bounded cleanup prevents expired keys from accumulating.
  if mod(extract(epoch from v_now)::bigint, 100) = 0 then
    delete from public.api_rate_limits
    where key_hash in (
      select key_hash from public.api_rate_limits
      where expires_at < v_now - interval '1 day'
      order by expires_at
      limit 500
    );
  end if;

  return pg_catalog.jsonb_build_object(
    'allowed', v_count <= p_limit,
    'limit', p_limit,
    'remaining', greatest(p_limit - v_count, 0),
    'retry_after', case when v_count <= p_limit then 0
      else greatest(1, ceil(extract(epoch from (v_expires - v_now)))) end,
    'reset_at', ceil(extract(epoch from v_expires))
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_allocation_plan_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if not exists (select 1 from public.network_plans p where p.id=new.plan_id and p.user_id=new.user_id) then
    raise exception 'Allocation plan ownership mismatch' using errcode='42501';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_ip_assignment_plan_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.plan_id is not null and not exists (
    select 1 from public.network_plans p
    where p.id=new.plan_id and p.user_id=new.user_id
  ) then
    raise exception 'IP assignment plan ownership mismatch' using errcode='42501';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_auth_audit_event(p_event text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare current_user_id uuid := (select auth.uid());
begin
 if current_user_id is null then raise exception 'Authentication required' using errcode='42501'; end if;
 if not (select public.is_email_otp_session_verified()) then raise exception 'Email OTP verification required' using errcode='42501'; end if;
 insert into public.auth_audit_log(event,user_id) values(p_event,current_user_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.record_ipam(p_kind text, p_user_id bigint, p_plan_id bigint, p_network_cidr text, p_family smallint, p_address text, p_address_int numeric, p_label text, p_mac text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  result_row jsonb;
begin
  if p_kind not in ('record','reservation') then
    raise exception using errcode = '22023', message = 'Invalid IPAM record type';
  end if;
  if not exists (select 1 from public.plans where id = p_plan_id and user_id = p_user_id) then
    raise exception using errcode = '42501', message = 'Plan ownership check failed';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_user_id::text || ':' || p_family::text || ':' || p_address_int::text, 0)
  );
  if exists (
    select 1 from public.ip_records
    where user_id = p_user_id and family = p_family and address_int = p_address_int and status = 'active'
    union all
    select 1 from public.reservations
    where user_id = p_user_id and family = p_family and address_int = p_address_int
  ) then
    raise exception using errcode = '23505', message = 'Address already assigned or reserved';
  end if;
  if p_kind = 'record' then
    insert into public.ip_records(user_id,plan_id,network_cidr,family,address,address_int,label,status)
    values(p_user_id,p_plan_id,p_network_cidr,p_family,p_address,p_address_int,p_label,'active')
    returning pg_catalog.to_jsonb(ip_records.*) into result_row;
  else
    if p_mac is null or p_mac !~ '^([0-9a-f]{2}:){5}[0-9a-f]{2}$' then
      raise exception using errcode = '22023', message = 'Invalid MAC address';
    end if;
    insert into public.reservations(user_id,plan_id,network_cidr,family,address,address_int,label,mac)
    values(p_user_id,p_plan_id,p_network_cidr,p_family,p_address,p_address_int,p_label,p_mac)
    returning pg_catalog.to_jsonb(reservations.*) into result_row;
  end if;
  return result_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_practice_attempt(p_user_id bigint, p_question_id uuid, p_topic text, p_difficulty text, p_correct boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  question_row public.practice_questions%rowtype;
begin
  select * into question_row from public.practice_questions
  where id = p_question_id and user_id = p_user_id for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'Question not found';
  end if;
  if question_row.topic <> p_topic or question_row.difficulty <> p_difficulty then
    raise exception using errcode = '22023', message = 'Question metadata mismatch';
  end if;
  insert into public.attempts(user_id,question_id,topic,difficulty,correct)
  values(p_user_id,p_question_id,p_topic,p_difficulty,p_correct);
  delete from public.practice_questions where id = p_question_id and user_id = p_user_id;
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_plan_guarded(p_user_id bigint, p_plan_id bigint, p_name text, p_family smallint, p_base text, p_data_json text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  plan_row public.plans%rowtype;
begin
  select * into plan_row from public.plans
  where id = p_plan_id and user_id = p_user_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'Plan not found';
  end if;
  if exists (select 1 from public.ip_records where user_id=p_user_id and plan_id=p_plan_id)
     or exists (select 1 from public.reservations where user_id=p_user_id and plan_id=p_plan_id) then
    if plan_row.family <> p_family
       or (plan_row.data_json::jsonb -> 'allocations') is distinct from (p_data_json::jsonb -> 'allocations') then
      raise exception using errcode = '23514', message = 'Plan changes would invalidate existing IPAM allocations';
    end if;
  end if;
  update public.plans
  set name=p_name, family=p_family, base=p_base, data_json=p_data_json, updated_at=pg_catalog.now()
  where id=p_plan_id and user_id=p_user_id
  returning * into plan_row;
  return pg_catalog.to_jsonb(plan_row);
end;
$function$
